import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, readFile, rm, mkdir, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
const profile = await mkdtemp(path.join(os.tmpdir(), 'legendgirl-som-chrome-'));
const chrome = spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', ['--headless=new', '--mute-audio', '--no-first-run', '--no-default-browser-check', '--autoplay-policy=no-user-gesture-required', '--remote-debugging-port=0', '--user-data-dir='+profile, 'about:blank'], {stdio:'ignore'});
let ws;
try {
 let port;
 for(let i=0;i<100;i++) { try { port=(await readFile(path.join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break; } catch {} await new Promise(r=>setTimeout(r,100)); }
 assert.ok(port,'Chrome de QA inicializado');
 const tabs=await (await fetch('http://127.0.0.1:'+port+'/json/list')).json();
 ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);
 await new Promise(r=>ws.onopen=r);
 let id=0;const pending=new Map();ws.onmessage=e=>{const d=JSON.parse(e.data);if(d.id){pending.get(d.id)?.(d);pending.delete(d.id);}};
 const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}));});
 const evaluate=async expression=>{const r=await call('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.result?.exceptionDetails)throw Error(JSON.stringify(r.result.exceptionDetails));return r.result?.result?.value;};

 const out='/tmp/legendgirl-pagina-final';await mkdir(out,{recursive:true});const report=[];
 for(const[name,width,height,mobile]of [['desktop',1280,800,false],['android',390,844,true],['paisagem',844,390,true]]){
  await call('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile});await call('Emulation.setTouchEmulationEnabled',{enabled:mobile});
  await call('Page.navigate',{url:'http://127.0.0.1:3000/'});for(let i=0;i<300;i++){if(await evaluate('Boolean(window.game)'))break;await new Promise(r=>setTimeout(r,100));}
  await evaluate(`(async()=>{await game.assetsReady;const select=document.querySelector('#debug-phase-select');select.value='garden';select.dispatchEvent(new Event('change',{bubbles:true}));})()`);
  for(let i=0;i<200;i++){if(await evaluate('Boolean(game.state.toyRoomInstance?.instance?.garden?.ready)'))break;await new Promise(r=>setTimeout(r,50));}
  await evaluate('game.setPaused(true)');
  for(const scene of ['solo','piquenique']){
   const checks=await evaluate(`(async()=>{
    const p=game.state.toyRoomInstance.instance.garden,{GARDEN:C,GARDEN_PLATFORM_BY_ID:map}=await import('/src/js/garden/GardenLevel.js');p.state.stage='${scene}'==='piquenique'?'COMPLETE':'RUNNING';p.state.age=4;p.state.time=12;const ground=map.get('${scene}'==='piquenique'?'arvore':'trecho-8-caminho');Object.assign(p.state.player,{x:'${scene}'==='piquenique'?C.goal:ground.x+100,y:ground.y,vx:0,vy:0,onGround:true,support:ground.id,terrain:ground.type,discomfort:0});Object.assign(p.state.fairy,{x:p.state.player.x,y:p.state.player.y-135});
    const ctx=p.renderer.ctx,draw=ctx.fillText;let progress;ctx.fillText=function(text,x,y,...args){if(text.includes('% do caminho'))progress={x,y};return draw.call(this,text,x,y,...args);};try{p.render();}finally{ctx.fillText=draw;}
    const rect=p.canvas.getBoundingClientRect(),buttons=document.querySelector('.top-controls-bar').getBoundingClientRect(),py=rect.top+progress.y/p.canvas.height*rect.height;if(py<=buttons.bottom)throw Error('Progresso coberto pelos botões');return{scene:'${scene}',progressY:py,buttonsBottom:buttons.bottom,canvas:{width:p.canvas.width,height:p.canvas.height}};
   })()`);report.push({name,...checks});const shot=await call('Page.captureScreenshot',{format:'png'});await writeFile(out+'/'+name+'-'+scene+'.png',Buffer.from(shot.result.data,'base64'));
  }
 }
 await writeFile('docs/diario-ia/qa/jardim-revisao/pagina-resultado.json',JSON.stringify(report,null,2));console.log(JSON.stringify(report));console.log('APROVADO: página real em três formatos, controles DOM, progresso legível e chegada.');
}finally{ws?.close();chrome.kill();await new Promise(r=>chrome.once('exit',r));await rm(profile,{recursive:true,force:true});}
